// Extrai e normaliza campos do payload do ClickUp
// O ClickUp envia um objeto 'task' com custom_fields como array
const body = $input.first().json.body || $input.first().json;
const task = body.task || body;
const customFields = task.custom_fields || [];

// Helper: busca campo personalizado por nome (case-insensitive)
const getCustomField = (name) => {
  const field = customFields.find(
    f => f.name?.toLowerCase().includes(name.toLowerCase())
  );
  if (!field) return '';
  // Lida com campos do tipo dropdown (type_config) e texto simples
  if (field.type === 'drop_down') {
    return field.type_config?.options?.find(o => o.orderindex === field.value)?.name || '';
  }
  return field.value || '';
};

return [{
  json: {
    task_id: task.id || ('TASK_' + Date.now()),
    task_name: task.name || 'Postagem sem título',
    description: task.description || '',
    legenda: getCustomField('legenda') || task.description || 'Legenda não informada',
    data_postagem: getCustomField('data') || new Date().toISOString().split('T')[0],
    tipo_conteudo: getCustomField('tipo') || 'feed',
    cliente: task.list?.name || task.folder?.name || 'Cliente não identificado',
    status: task.status?.status || 'aprovado',
    processed_at: new Date().toISOString()
  }
}];

