// Processa a resposta do Gemini e monta o objeto final
const aiResponse = $input.first().json;
const taskData = $('Extrair Dados da Tarefa').first().json;

let hashtags = '';
try {
  // Gemini retorna: candidates[0].content.parts[0].text
  hashtags = aiResponse.candidates[0].content.parts[0].text.trim();
} catch (e) {
  // Fallback com hashtags genéricas se a IA não responder
  hashtags = '#marketing #instagram #saude #profissional #conteudo #branding #autoridade #medico #dentista #advogado';
  console.log('FALLBACK: usando hashtags padrão. Erro:', e.message);
}

// Garante que todas as tags começam com #
hashtags = hashtags
  .split(/\s+/)
  .filter(t => t.length > 0)
  .map(t => t.startsWith('#') ? t : '#' + t)
  .join(' ');

const tokensUsed = aiResponse.usageMetadata?.candidatesTokenCount || 0;

return [{
  json: {
    ...taskData,
    hashtags,
    ia_model: 'gemini-1.5-flash',
    full_caption: taskData.legenda + '\n\n' + hashtags,
    ia_tokens_used: tokensUsed
  }
}];

